local function C_4e()
local script = G2L["4e"];
	local button = script.Parent
	local ReplicatedStorage = game:GetService("ReplicatedStorage")
	local Players = game:GetService("Players")
	local RunService = game:GetService("RunService")
	local COREGUI = game:GetService("CoreGui")
	local LP = Players.LocalPlayer
	local ESPenabled = false

	-- Functions for creating and updating highlights
	local function CreateAllHighlight()
		for _, player in pairs(Players:GetPlayers()) do
			if player ~= LP and player.Character and not player.Character:FindFirstChild("Highlight") then
				local highlight = Instance.new("Highlight")
				highlight.Parent = player.Character
				highlight.FillColor = Color3.fromRGB(0, 225, 0)
			end
		end
	end

	local function UpdateAllHighlights()
		for _, player in pairs(Players:GetPlayers()) do
			if player ~= LP and player.Character then
				local highlight = player.Character:FindFirstChild("Highlight")
				if highlight then
					highlight.FillColor = Color3.fromRGB(0, 225, 0)
				end
			end
		end
	end

	local function ClearAllHighlights()
		for _, player in pairs(Players:GetPlayers()) do
			if player.Character then
				local highlight = player.Character:FindFirstChild("Highlight")
				if highlight then
					highlight:Destroy()
				end
			end
		end
	end

	-- ESP Creation
	local function CreateESP(player)
		if player.Character and player.Character:FindFirstChild("Head") then
			local ESPholder = Instance.new("Folder")
			ESPholder.Name = player.Name .. "_ESP"
			ESPholder.Parent = COREGUI

			local BillboardGui = Instance.new("BillboardGui")
			BillboardGui.Adornee = player.Character.Head
			BillboardGui.Name = player.Name
			BillboardGui.Parent = ESPholder
			BillboardGui.Size = UDim2.new(0, 100, 0, 150)
			BillboardGui.StudsOffset = Vector3.new(0, 1, 0)
			BillboardGui.AlwaysOnTop = true

			local TextLabel = Instance.new("TextLabel")
			TextLabel.Parent = BillboardGui
			TextLabel.BackgroundTransparency = 1
			TextLabel.Position = UDim2.new(0, 0, 0, -50)
			TextLabel.Size = UDim2.new(0, 100, 0, 100)
			TextLabel.Font = Enum.Font.SourceSansSemibold
			TextLabel.TextSize = 17
			TextLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
			TextLabel.TextStrokeTransparency = 0.3
			TextLabel.TextYAlignment = Enum.TextYAlignment.Bottom
			TextLabel.Text = '@' .. player.Name .. ' | ' .. player.DisplayName
			TextLabel.ZIndex = 10
		end
	end

	local function RemoveESP(player)
		local ESP = COREGUI:FindFirstChild(player.Name .. "_ESP")
		if ESP then
			ESP:Destroy()
		end
	end

	-- Manage Highlights and ESP when button is clicked
	button.MouseButton1Down:Connect(function()
		if button.Text == "Off" then
			ESPenabled = true
			CreateAllHighlight()
			UpdateAllHighlights()

			for _, player in pairs(Players:GetPlayers()) do
				if player ~= LP then
					RemoveESP(player)
					CreateESP(player)

					player.CharacterAdded:Connect(function()
						wait(2)
						CreateAllHighlight()
						UpdateAllHighlights()
						if ESPenabled then
							RemoveESP(player)
							CreateESP(player)
						end
					end)
				end
			end

			button.Text = "On"
		else
			ESPenabled = false
			ClearAllHighlights()
			for _, player in pairs(Players:GetPlayers()) do
				RemoveESP(player)
			end
			button.Text = "Off"
		end
	end)

end;
