			local rb = p(nil,"Block",1,1,1,true,false,1,0.1,BladeColor)
			rb.CFrame = CFrame.new((brick1.CFrame *cf(10,0,0)).p)
			local posml = math.abs((posd - rb.Position).magnitude)
